  },

  /** Idempotent: runs on every start (ADR-0001, ADR-0002). */
  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
    await reconcileRolePermissions(strapi);
    await ensureDevAdmin(strapi);
    await deleteDefaultFullAccessToken(strapi);
    await seed(strapi);
  },
};
